93	    public static Value ConvertToGrpcFieldValue(object? sourceValue)
94	    {
95	        var value = new Value();
96	        if (sourceValue is null)
97	        {
98	            value.NullValue = NullValue.NullValue;
99	        }
100	        else if (sourceValue is int intValue)
101	        {
102	            value.IntegerValue = intValue;
103	        }
104	        else if (sourceValue is long longValue)
105	        {
106	            value.IntegerValue = longValue;
107	        }
108	        else if (sourceValue is string stringValue)
109	        {
110	            value.StringValue = stringValue;
111	        }
112	        else if (sourceValue is float floatValue)
113	        {
114	            value.DoubleValue = floatValue;
115	        }
116	        else if (sourceValue is double doubleValue)
117	        {
118	            value.DoubleValue = doubleValue;
119	        }
120	        else if (sourceValue is bool boolValue)
121	        {
122	            value.BoolValue = boolValue;
123	        }
124	        else if (sourceValue is IEnumerable<int> ||
125	            sourceValue is IEnumerable<long> ||
126	            sourceValue is IEnumerable<string> ||
127	            sourceValue is IEnumerable<float> ||
128	            sourceValue is IEnumerable<double> ||
129	            sourceValue is IEnumerable<bool>)
130	        {
131	            var listValue = sourceValue as IEnumerable;
132	            value.ListValue = new ListValue();
133	            foreach (var item in listValue!)
134	            {
135	                value.ListValue.Values.Add(ConvertToGrpcFieldValue(item));
136	            }
137	        }
138	        else
139	        {
140	            throw new VectorStoreRecordMappingException($"Unsupported source value type {sourceValue?.GetType().FullName}.");
141	        }
